 21	#[derive(Parser)]
 22	#[command(name = "sealmap", version, about = "Deterministic codebase → Mermaid corpus generator")]
 23	struct Cli {
 24	    #[command(subcommand)]
 25	    cmd: Cmd,
 26	}
 27	
 28	#[derive(Subcommand)]
 29	enum Cmd {
 30	    /// Generate the corpus and write it into the output directory.
 31	    Generate(Common),
 32	    /// Check the output directory against the sources. Exits 1 on drift.
 33	    Verify(Common),
 34	    /// Print the extracted model as JSON to stdout.
 35	    Model(Common),
 36	}
