 38	#[derive(Args)]
 39	struct Common {
 40	    /// Source root (ignored when --repo is given).
 41	    #[arg(default_value = ".")]
 42	    path: PathBuf,
 43	    /// Add a repository as NAME=PATH (repeatable) to analyse several together.
 44	    #[arg(long = "repo", value_name = "NAME=PATH")]
 45	    repos: Vec<String>,
 46	    /// Corpus directory.
 47	    #[arg(short, long, default_value = ".sealmap")]
 48	    out: PathBuf,
 49	    /// Codebase name (defaults to the directory or repo names).
 50	    #[arg(long)]
 51	    name: Option<String>,
 52	    /// Include tests, examples and benches.
 53	    #[arg(long)]
 54	    tests: bool,
 55	    /// External calls to keep in flows: all, non-std, none.
 56	    #[arg(long, default_value = "non-std")]
 57	    external: String,
 58	    /// One sequence lane per external owner instead of per crate.
 59	    #[arg(long)]
 60	    owner_lanes: bool,
 61	    /// Minimum calls for a function to get a sequence diagram.
 62	    #[arg(long, default_value_t = 1)]
 63	    min_calls: usize,
 64	    /// Leave private items out of structure diagrams.
 65	    #[arg(long)]
 66	    public_only: bool,
 67	    /// Do not write _model.json.
 68	    #[arg(long)]
 69	    no_model: bool,
 70	    /// Pretty-print _index.json and _model.json.
 71	    #[arg(long)]
 72	    pretty: bool,
 73	}
