 75	fn main() -> ExitCode {
 76	    let cli = Cli::parse();
 77	    match run(cli) {
 78	        Ok(code) => code,
 79	        Err(e) => {
 80	            eprintln!("sealmap: {e}");
 81	            ExitCode::from(2)
 82	        }
 83	    }
 84	}
 85	
 86	fn run(cli: Cli) -> Result<ExitCode, String> {
 87	    let (Cmd::Generate(c) | Cmd::Verify(c) | Cmd::Model(c)) = &cli.cmd;
 88	    let mut opts = Options::default();
 89	    if let Some(n) = &c.name {
 90	        opts.rust.name = n.clone();
 91	    }
 92	    opts.rust.include_tests = c.tests;
 93	    opts.rust.external_calls = match c.external.as_str() {
 94	        "all" => ExternalCalls::All,
 95	        "non-std" => ExternalCalls::NonStd,
 96	        "none" => ExternalCalls::None,
 97	        other => return Err(format!("--external must be all, non-std or none (got `{other}`)")),
 98	    };
 99	    opts.corpus.min_calls = c.min_calls;
100	    opts.corpus.include_private = !c.public_only;
101	    opts.corpus.emit_model = !c.no_model;
102	    opts.corpus.pretty_json = c.pretty;
103	    if c.owner_lanes {
104	        opts.corpus.external_lanes = ExternalLanes::Owner;
105	    }
106	
107	    let (sources, rust_opts) = load(c, &opts)?;
108	    let extraction = sealmap::rust::extract(&sources, &rust_opts);
109	    for d in &extraction.diagnostics {
110	        eprintln!("warning: {}: {}", d.file, d.message);
111	    }
112	
113	    if let Cmd::Model(_) = cli.cmd {
114	        let json = serde_json::to_string_pretty(&extraction.codebase).map_err(|e| e.to_string())?;
115	        println!("{json}");
116	        return Ok(ExitCode::SUCCESS);
117	    }
118	
119	    let corpus = sealmap::generate(&extraction.codebase, &opts.corpus);
120	    let stats = extraction.codebase.stats();
121	    match cli.cmd {
122	        Cmd::Generate(_) => {
123	            let report = corpus::write(&c.out, &corpus).map_err(|e| e.to_string())?;
124	            eprintln!(
125	                "sealmap: {} files, {} symbols, {} sequences → {} ({} written, {} removed, {} unchanged)",
126	                stats.files,
127	                stats.symbols,
128	                corpus.index.fragments().filter(|f| f.kind == corpus::FragmentKind::Sequence).count(),
129	                c.out.display(),
130	                report.entries.len() - report.count(Drift::Orphaned),
131	                report.count(Drift::Orphaned),
132	                report.checked - (report.entries.len() - report.count(Drift::Orphaned)),
133	            );
134	            Ok(ExitCode::SUCCESS)
135	        }
136	        Cmd::Verify(_) => {
137	            let report = corpus::verify(&c.out, &corpus).map_err(|e| e.to_string())?;
138	            for e in &report.entries {
139	                println!("{:<9} {}", e.drift, e.path);
140	            }
141	            if report.is_clean() {
142	                eprintln!("sealmap: corpus in {} is up to date ({} files)", c.out.display(), report.checked);
143	                Ok(ExitCode::SUCCESS)
144	            } else {
145	                eprintln!("sealmap: {} files drifted; run `sealmap generate`", report.entries.len());
146	                Ok(ExitCode::from(1))
147	            }
148	        }
149	        Cmd::Model(_) => unreachable!("handled above"),
150	    }
151	}
