153	fn load(c: &Common, opts: &Options) -> Result<(SourceSet, sealmap::rust::RustOptions), String> {
154	    let mut ro = opts.rust.clone();
155	    if c.repos.is_empty() {
156	        // Load only: `run` extracts once. (Calling `extract_dir` here ran the
157	        // whole language adapter twice and threw the first result away.)
158	        let sources = sealmap::rust::load_dir(&c.path).map_err(|e| format!("{}: {e}", c.path.display()))?;
159	        if ro.name == "codebase" {
160	            ro.name = dir_name(&c.path);
161	        }
162	        return Ok((sources, ro));
163	    }
164	    let mut repos = Vec::new();
165	    for r in &c.repos {
166	        let (name, path) = r.split_once('=').ok_or_else(|| format!("--repo expects NAME=PATH, got `{r}`"))?;
167	        repos.push((name.to_owned(), PathBuf::from(path)));
168	    }
169	    let refs: Vec<(&str, &Path)> = repos.iter().map(|(n, p)| (n.as_str(), p.as_path())).collect();
170	    let sources = sealmap::load_repos(&refs).map_err(|e| e.to_string())?;
171	    if ro.name == "codebase" {
172	        ro.name = repos.iter().map(|(n, _)| n.as_str()).collect::<Vec<_>>().join("+");
173	    }
174	    Ok((sources, ro))
175	}
