177	fn dir_name(p: &Path) -> String {
178	    p.canonicalize()
179	        .ok()
180	        .and_then(|p| p.file_name().map(|s| s.to_string_lossy().into_owned()))
181	        .unwrap_or_else(|| "codebase".into())
182	}
570	    };
571	    match shape {
572	        Shape::Fields(Fields::Named(n)) | Shape::Named(n) => fields(&mut body, "named", &mut n.named.iter()),
573	        Shape::Fields(Fields::Unnamed(u)) => fields(&mut body, "unnamed", &mut u.unnamed.iter()),
574	        Shape::Fields(Fields::Unit) => body.section("unit"),
575	        Shape::Variants(vs) => {
576	            for v in vs {
577	                body.section("variant");
578	                fingerprint::attrs(&mut body, &v.attrs);
579	                body.ident(&v.ident.to_string());
580	                match &v.fields {
581	                    Fields::Named(n) => fields(&mut body, "named", &mut n.named.iter()),
582	                    Fields::Unnamed(u) => fields(&mut body, "unnamed", &mut u.unnamed.iter()),
583	                    Fields::Unit => body.section("unit"),
584	                }
585	                if let Some((_, discriminant)) = &v.discriminant {
586	                    body.section("discriminant");
587	                    fingerprint::feed_canonical(&mut body, discriminant, Canon::visit_expr_mut);
588	                }
589	            }
590	        }
591	    }
592	    (sig.finish(), body.finish())
593	}
