595	/// A trait: the header plus every member's signature is the contract; every
596	/// member in full (default bodies included) is the body.
597	fn trait_hashes(t: &syn::ItemTrait) -> (Fingerprint, Fingerprint) {
598	    let mut sig = Fingerprinter::sig();
599	    sig.section("trait");
600	    fingerprint::attrs(&mut sig, &t.attrs);
601	    fingerprint::feed(&mut sig, &t.vis);
602	    fingerprint::feed(&mut sig, &t.unsafety);
603	    fingerprint::feed(&mut sig, &t.auto_token);
604	    sig.ident(&t.ident.to_string());
605	    fingerprint::feed(&mut sig, &t.generics);
606	    sig.section("supertraits");
607	    fingerprint::feed(&mut sig, &t.supertraits);
608	    fingerprint::feed(&mut sig, &t.generics.where_clause);
609	    let mut body = Fingerprinter::body();
610	    body.section("trait");
611	    fingerprint::feed(&mut body, &t.generics);
612	    fingerprint::feed(&mut body, &t.generics.where_clause);
613	    for ti in &t.items {
614	        sig.section("item");
615	        match ti {
616	            TraitItem::Fn(f) => {
617	                fingerprint::attrs(&mut sig, &f.attrs);
618	                fingerprint::feed(&mut sig, &f.sig);
619	            }
620	            TraitItem::Const(k) => {
621	                fingerprint::attrs(&mut sig, &k.attrs);
622	                sig.ident(&k.ident.to_string());
623	                fingerprint::feed(&mut sig, &k.generics);
624	                fingerprint::feed(&mut sig, &k.ty);
625	            }
626	            other => fingerprint::feed(&mut sig, other),
627	        }
628	        body.section("item");
629	        fingerprint::feed_canonical(&mut body, ti, Canon::visit_trait_item_mut);
630	    }
631	    (sig.finish(), body.finish())
632	}
