634	/// A constant or static: everything but the value is the contract; the
635	/// value is the body.
636	fn value(
637	    keyword: &str,
638	    attrs: &[Attribute],
639	    vis: &syn::Visibility,
640	    mutability: Option<&syn::StaticMutability>,
641	    ident: &syn::Ident,
642	    ty: &Type,
643	    expr: &Expr,
644	) -> (Fingerprint, Fingerprint) {
645	    let mut sig = Fingerprinter::sig();
646	    sig.section(keyword);
647	    fingerprint::attrs(&mut sig, attrs);
648	    fingerprint::feed(&mut sig, vis);
649	    if let Some(m) = mutability {
650	        fingerprint::feed(&mut sig, m);
651	    }
652	    sig.ident(&ident.to_string());
653	    fingerprint::feed(&mut sig, ty);
654	    let mut body = Fingerprinter::body();
655	    body.section(keyword);
656	    fingerprint::feed_canonical(&mut body, expr, Canon::visit_expr_mut);
657	    (sig.finish(), body.finish())
658	}
