662	fn span_of(s: PmSpan) -> Span {
663	    let (a, b) = (s.start(), s.end());
664	    Span::new(a.line as u32, a.column as u32 + 1, b.line as u32, b.column as u32 + 1)
665	}
666	
667	fn vis_of(v: &syn::Visibility) -> Visibility {
668	    match v {
669	        syn::Visibility::Public(_) => Visibility::Public,
670	        syn::Visibility::Restricted(r) if r.path.is_ident("crate") => Visibility::Crate,
671	        syn::Visibility::Restricted(r) => Visibility::Restricted(tokens(&r.path)),
672	        syn::Visibility::Inherited => Visibility::Private,
673	    }
674	}
675	
676	fn vis_prefix(v: &syn::Visibility) -> String {
677	    match v {
678	        syn::Visibility::Inherited => String::new(),
679	        v => format!("{} ", tokens(v)),
680	    }
681	}
