683	fn is_test_attr(a: &Attribute) -> bool {
684	    let p = a.path();
685	    if p.is_ident("test") || p.segments.last().is_some_and(|s| s.ident == "test") {
686	        return true;
687	    }
688	    p.is_ident("cfg") && tokens(&a.meta).replace(' ', "") == "cfg(test)"
689	}
