691	/// First sentence of the doc comment, at most 160 chars.
692	fn doc_of(attrs: &[Attribute]) -> Option<String> {
693	    let mut text = String::new();
694	    for a in attrs {
695	        if let syn::Meta::NameValue(nv) = &a.meta {
696	            if nv.path.is_ident("doc") {
697	                if let Expr::Lit(syn::ExprLit { lit: syn::Lit::Str(s), .. }) = &nv.value {
698	                    let line = s.value();
699	                    let line = line.trim();
700	                    if line.is_empty() && !text.is_empty() {
701	                        break; // end of first paragraph
702	                    }
703	                    if line.starts_with('#') || line.starts_with("```") {
704	                        if text.is_empty() { continue } else { break }
705	                    }
706	                    if !text.is_empty() {
707	                        text.push(' ');
708	                    }
709	                    text.push_str(line);
710	                }
711	            }
712	        }
713	    }
714	    let text = text.trim();
715	    if text.is_empty() {
716	        return None;
717	    }
718	    let first = match text.find(". ") {
719	        Some(i) => &text[..=i],
720	        None => text,
721	    };
722	    Some(clip(first, DOC_SUMMARY_MAX))
723	}
724	
725	/// Attributes worth keeping as tags.
726	fn tags_of(attrs: &[Attribute]) -> Vec<String> {
727	    const KEEP: &[&str] = &["derive", "cfg", "deprecated", "non_exhaustive", "repr", "must_use", "async_trait", "test"];
728	    let mut out = Vec::new();
729	    for a in attrs {
730	        let p = a.path();
731	        let multi = p.segments.len() > 1;
732	        if multi || KEEP.iter().any(|k| p.is_ident(k)) {
733	            let t = squeeze(&tokens(&a.meta));
734	            out.push(clip(&t, LABEL_MAX));
735	        }
736	    }
737	    out
738	}
