740	fn fn_tags(sig: &syn::Signature, attrs: &[Attribute]) -> Vec<String> {
741	    let mut t = tags_of(attrs);
742	    if sig.constness.is_some() {
743	        t.push("const".into());
744	    }
745	    if sig.asyncness.is_some() {
746	        t.push("async".into());
747	    }
748	    if sig.unsafety.is_some() {
749	        t.push("unsafe".into());
750	    }
751	    t
752	}
