754	fn generics_of(g: &Generics) -> Vec<String> {
755	    g.params
756	        .iter()
757	        .map(|p| match p {
758	            GenericParam::Type(t) => squeeze(&tokens(t)),
759	            GenericParam::Lifetime(l) => squeeze(&tokens(l)),
760	            GenericParam::Const(c) => squeeze(&tokens(c)),
761	        })
762	        .collect()
763	}
