765	fn fields_of(fields: &Fields) -> Vec<RawMember> {
766	    fields
767	        .iter()
768	        .enumerate()
769	        .map(|(i, f)| {
770	            let mut refs = Vec::new();
771	            type_refs(&f.ty, &mut refs);
772	            RawMember {
773	                name: f.ident.as_ref().map_or_else(|| i.to_string(), ToString::to_string),
774	                kind: MemberKind::Field,
775	                ty: Some(tokens(&f.ty)),
776	                vis: vis_of(&f.vis),
777	                span: span_of(f.span()),
778	                refs,
779	            }
780	        })
781	        .collect()
782	}
