784	pub(crate) fn path_segs(p: &syn::Path) -> Segs {
785	    p.segments.iter().map(|s| s.ident.to_string()).collect()
786	}
787	
788	/// Every path mentioned in a type, outermost first.
789	fn type_refs(ty: &Type, out: &mut Vec<Segs>) {
790	    struct V<'a>(&'a mut Vec<Segs>);
791	    impl<'ast> syn::visit::Visit<'ast> for V<'_> {
792	        fn visit_path(&mut self, p: &'ast syn::Path) {
793	            let segs = path_segs(p);
794	            if !self.0.contains(&segs) {
795	                self.0.push(segs);
796	            }
797	            syn::visit::visit_path(self, p);
798	        }
799	    }
800	    syn::visit::Visit::visit_type(&mut V(out), ty);
801	}
802	
803	fn sig_refs(sig: &syn::Signature, out: &mut Vec<Segs>) {
804	    for input in &sig.inputs {
805	        if let FnArg::Typed(t) = input {
806	            type_refs(&t.ty, out);
807	        }
808	    }
809	    if let syn::ReturnType::Type(_, ty) = &sig.output {
810	        type_refs(ty, out);
811	    }
812	}
813	
814	/// Outermost path of a type, looking through references and parens.
815	fn first_path(ty: &Type) -> Option<Segs> {
816	    match ty {
817	        Type::Path(p) => Some(path_segs(&p.path)),
818	        Type::Reference(r) => first_path(&r.elem),
819	        Type::Paren(p) => first_path(&p.elem),
820	        Type::Group(g) => first_path(&g.elem),
821	        _ => None,
822	    }
823	}
824	
825	fn params_of(sig: &syn::Signature) -> BTreeMap<String, Recv> {
826	    let mut env = BTreeMap::new();
827	    for input in &sig.inputs {
828	        match input {
829	            FnArg::Receiver(_) => {
830	                env.insert("self".to_owned(), Recv::SelfValue);
831	            }
832	            FnArg::Typed(t) => {
833	                if let Pat::Ident(id) = &*t.pat {
834	                    let mut refs = Vec::new();
835	                    type_refs(&t.ty, &mut refs);
836	                    env.insert(id.ident.to_string(), Recv::Typed(refs));
837	                }
838	            }
839	        }
840	    }
841	    env
842	}
843	
844	fn flatten_use(tree: &UseTree, prefix: &mut Segs, out: &mut Vec<RawUse>) {
845	    match tree {
846	        UseTree::Path(p) => {
847	            prefix.push(p.ident.to_string());
848	            flatten_use(&p.tree, prefix, out);
849	            prefix.pop();
850	        }
851	        UseTree::Name(n) => {
852	            let name = n.ident.to_string();
853	            if name == "self" {
854	                if let Some(last) = prefix.last() {
855	                    out.push(RawUse { alias: last.clone(), target: prefix.clone() });
856	                }
857	            } else {
858	                let mut t = prefix.clone();
859	                t.push(name.clone());
860	                out.push(RawUse { alias: name, target: t });
861	            }
862	        }
863	        UseTree::Rename(r) => {
864	            let mut t = prefix.clone();
865	            if r.ident != "self" {
866	                t.push(r.ident.to_string());
867	            }
868	            out.push(RawUse { alias: r.rename.to_string(), target: t });
869	        }
