  1326	    /// `format!("{}", h())`). Macros that do not parse as comma-separated
  1327	    /// expressions are skipped.
  1328	    fn mac(&mut self, m: &syn::Macro, out: &mut Vec<RawStep>) {
  1329	        let parser = Punctuated::<Expr, syn::Token![,]>::parse_terminated;
  1330	        if let Ok(args) = m.parse_body_with(parser) {
  1331	            for a in &args {
  1332	                self.expr(a, out);
  1333	            }
  1334	        } else if let Ok(stmts) = m.parse_body_with(Block::parse_within) {
  1335	            self.stmts(&stmts, out);
  1336	        }
