  1339	    fn recv(&self, e: &Expr) -> Recv {
  1340	        match e {
  1341	            Expr::Path(p) if p.path.segments.len() == 1 => {
  1342	                let name = p.path.segments[0].ident.to_string();
  1343	                self.env.get(&name).cloned().unwrap_or(Recv::Untyped)
  1344	            }
  1345	            Expr::Field(f) => match (&*f.base, &f.member) {
  1346	                (Expr::Path(p), syn::Member::Named(n)) if p.path.is_ident("self") => Recv::SelfField(n.to_string()),
  1347	                (Expr::Path(_) | Expr::Field(_), syn::Member::Named(_)) => Recv::Untyped,
  1348	                _ => Recv::Unknown,
  1349	            },
  1350	            Expr::Paren(p) => self.recv(&p.expr),
  1351	            Expr::Reference(r) => self.recv(&r.expr),
  1352	            Expr::Unary(u) => self.recv(&u.expr),
  1353	            _ => Recv::Unknown,
  1354	        }
  1355	    }
  1356	}
