  1358	/// The type the single name bound by `pat` gets from a scrutinee of
  1359	/// declared type `refs` (outermost first), when the shape says so.
  1360	fn peel(pat: &Pat, refs: &[Segs], iterated: bool) -> Option<Vec<Segs>> {
  1361	    const ONE_PARAMETER: &[&str] =
  1362	        &["Vec", "VecDeque", "HashSet", "BTreeSet", "IndexSet", "Option", "BinaryHeap", "LinkedList"];
  1363	    let outer = refs.first()?.last()?.as_str();
  1364	    let arg = |i: usize| refs.get(i).map(|r| vec![r.clone()]);
  1365	    if iterated {
  1366	        return if ONE_PARAMETER.contains(&outer) && refs.len() == 2 { arg(1) } else { None };
  1367	    }
  1368	    let Pat::TupleStruct(ts) = pat else { return None };
  1369	    match ts.path.segments.last()?.ident.to_string().as_str() {
  1370	        "Some" if outer == "Option" => arg(1),
  1371	        "Ok" if outer == "Result" => arg(1),
  1372	        "Err" if outer == "Result" => arg(2),
  1373	        // A value known only by its own type, as a constructor or turbofish
  1374	        // gives it (`Ok(store) = RoleStore::new(..).await`,
  1375	        // `Some(m) = any.downcast_ref::<Metrics>()`): the wrapper is implied,
  1376	        // the payload is that type.
  1377	        "Some" | "Ok" if refs.len() == 1 && !["Option", "Result"].contains(&outer) => arg(0),
  1378	        _ => None,
  1379	    }
  1380	}
