  1382	/// The type paths of a turbofish with exactly one type argument
  1383	/// (`::<Config>`, `::<Vec<Job>>`).
  1384	fn turbofish_refs(args: &Punctuated<syn::GenericArgument, syn::Token![,]>) -> Option<Vec<Segs>> {
  1385	    let mut types = args.iter().filter_map(|a| match a {
  1386	        syn::GenericArgument::Type(t) => Some(t),
  1387	        _ => None,
  1388	    });
  1389	    let (Some(ty), None) = (types.next(), types.next()) else { return None };
  1390	    let mut refs = Vec::new();
  1391	    type_refs(ty, &mut refs);
  1392	    (!refs.is_empty()).then_some(refs)
  1393	}
