 185	flowchart TB
 186	    CMD["generate, verify, model<br/>main.rs:28-36"]
 187	    FL["flags: --repo, -o, --name, --tests,<br/>--external, --owner-lanes, --min-calls,<br/>--public-only, --no-model, --pretty<br/>main.rs:38-73"]
