 182	/// Generate the full corpus in memory. Pure and deterministic: equal inputs
 183	/// give byte-identical output.
 184	pub fn generate(codebase: &Codebase, options: &CorpusOptions) -> Corpus {
 185	    let mut files = BTreeMap::new();
 186	    naming::assert_unique_idents(codebase);
 187	    let mut index = Index::new(codebase);
 188	    let lookup = Lookup::new(codebase);
 189	    for file in codebase.files.values() {
 190	        let (path, text, entry) = document::render(codebase, &lookup, file, options);
 191	        index.documents.push(entry);
 192	        files.insert(path, text);
 193	    }
 194	    index.link_expansions();
 195	    let reserved = |name: &str| SourcePath::new(name).expect("reserved names are valid paths");
 196	    files.insert(reserved("_overview.md"), overview::render(codebase, options));
 197	    files.insert(reserved("_README.md"), readme());
 198	    if options.emit_model {
 199	        files.insert(reserved("_model.json"), to_json(codebase, options.pretty_json));
 200	    }
 201	    files.insert(reserved("_index.json"), to_json(&index, options.pretty_json));
 202	    Corpus { files, index }
 203	}
