 205	/// Per-file and per-parent symbol lists, built once per [`generate`] call.
 206	///
 207	/// `Codebase::symbols_in_file` and `Codebase::children` scan every symbol;
 208	/// calling them per document made projection O(files × symbols).
 209	pub(crate) struct Lookup<'a> {
 210	    by_file: BTreeMap<&'a SourcePath, Vec<&'a Symbol>>,
 211	    children: BTreeMap<&'a SymbolId, Vec<&'a Symbol>>,
 212	}
 213	
 214	impl<'a> Lookup<'a> {
 215	    fn new(cb: &'a Codebase) -> Self {
 216	        let mut by_file: BTreeMap<&SourcePath, Vec<&Symbol>> = BTreeMap::new();
 217	        let mut children: BTreeMap<&SymbolId, Vec<&Symbol>> = BTreeMap::new();
 218	        // `symbols` iterates in id order, so each list keeps the order the
 219	        // linear scans produced.
 220	        for s in cb.symbols.values() {
 221	            by_file.entry(&s.file).or_default().push(s);
 222	            if let Some(p) = &s.parent {
 223	                children.entry(p).or_default().push(s);
 224	            }
 225	        }
