  72	/// Compare `expected` (freshly generated) with `actual` (file path → text as
  73	/// found on disk or elsewhere).
  74	///
  75	/// Only `.md` files that carry the sealmap header, and the reserved `_`
  76	/// files, are considered part of the corpus; anything else in the directory
  77	/// is ignored.
  78	pub fn verify_against(expected: &Corpus, actual: &BTreeMap<SourcePath, String>) -> Report {
  79	    let mut entries = Vec::new();
  80	    for (path, want) in &expected.files {
  81	        match actual.get(path) {
  82	            None => entries.push(DriftEntry { path: path.clone(), drift: Drift::Missing }),
  83	            Some(have) if have == want => {}
  84	            Some(have) => {
  85	                let drift = if is_reserved(path) {
  86	                    Drift::Modified
  87	                } else {
  88	                    let want_hash = front_matter_hash(want);
  89	                    match front_matter_hash(have) {
  90	                        Some(h) if Some(&h) == want_hash.as_ref() => Drift::Modified,
  91	                        _ => Drift::Stale,
  92	                    }
  93	                };
  94	                entries.push(DriftEntry { path: path.clone(), drift });
  95	            }
  96	        }
  97	    }
  98	    for (path, text) in actual {
  99	        if !expected.files.contains_key(path) && path.extension() == Some("md") && is_generated(text) {
 100	            entries.push(DriftEntry { path: path.clone(), drift: Drift::Orphaned });
 101	        }
 102	    }
 103	    entries.sort();
 104	    Report { entries, checked: expected.files.len() }
 105	}
